<?php
declare(strict_types=1);
// Member-only persistent authentication. Never grants administrator access.
function memberRememberName(): string {return 'tripovela_member_'.substr(hash('sha256',APP_URL),0,10);}
function memberRememberSchema(): void {static $done=false;if($done)return;socialQuery('CREATE TABLE IF NOT EXISTS member_remember(token_hash TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES members(id),session_version INTEGER NOT NULL,expires INTEGER NOT NULL)');socialQuery('CREATE INDEX IF NOT EXISTS member_remember_expiry ON member_remember(expires)');$done=true;}
function memberRememberCookie(string $token,int $expires): void {setcookie(memberRememberName(),$token,['expires'=>$expires,'path'=>'/','secure'=>APP_ENV!=='local','httponly'=>true,'samesite'=>'Lax']);if($token==='')unset($_COOKIE[memberRememberName()]);else $_COOKIE[memberRememberName()]=$token;}
function memberRememberForget(): void {if(qaActive()||amViewing())return;memberRememberSchema();$token=$_COOKIE[memberRememberName()]??'';if(is_string($token)&&preg_match('/^[a-f0-9]{64}$/D',$token))socialQuery('DELETE FROM member_remember WHERE token_hash=?',[hash('sha256',$token)]);memberRememberCookie('',time()-3600);unset($_SESSION['member_remember_checked']);}
function memberRememberIssue(array $u): void {if(qaActive()||amViewing())return;memberRememberForget();socialQuery('DELETE FROM member_remember WHERE expires<=?',[time()]);$token=bin2hex(random_bytes(32));$expires=time()+365*86400;socialQuery('INSERT INTO member_remember(token_hash,member_id,session_version,expires) VALUES(?,?,?,?)',[hash('sha256',$token),$u['id'],(int)($u['session_version']??1),$expires]);memberRememberCookie($token,$expires);$_SESSION['member_remember_checked']=true;}
function memberRememberRestore(): ?array {if(qaActive()||amViewing())return null;memberRememberSchema();$token=$_COOKIE[memberRememberName()]??'';if(!is_string($token)||!preg_match('/^[a-f0-9]{64}$/D',$token))return null;
 $u=socialQuery('SELECT m.id,m.handle,m.state,m.session_version FROM member_remember r JOIN members m ON m.id=r.member_id WHERE r.token_hash=? AND r.expires>? AND r.session_version=m.session_version AND m.state=?',[hash('sha256',$token),time(),'active'])->fetch();
 if(!$u){memberRememberForget();return null;}memberRememberRenew();session_regenerate_id(true);$_SESSION['member_id']=$u['id'];$_SESSION['member_version']=$u['session_version'];$_SESSION['member_seen']=time();$_SESSION['member_remember_checked']=true;return $u;
}

function memberRememberRenew(): void {if(qaActive()||amViewing()||($_SESSION['member_remember_renewed']??0)>time()-86400)return;$token=$_COOKIE[memberRememberName()]??'';if(!is_string($token)||!preg_match('/^[a-f0-9]{64}$/D',$token))return;memberRememberSchema();$expiry=time()+365*86400;$q=socialQuery('UPDATE member_remember SET expires=? WHERE token_hash=? AND expires>?',[$expiry,hash('sha256',$token),time()]);if($q->rowCount()){memberRememberCookie($token,$expiry);$_SESSION['member_remember_renewed']=time();}}
